type Role = 'customer' | 'owner';
type Machinery = { id:string; title:string; category:string; owner:string; rating:number; distanceKm:number; baseRateHourly:number; location:string; verified:boolean; availability:string; specs:string[]; plainEnglishGuide:string; primaryApplication:string; fuelPct:number; engineHours:number; telematicsId:string; status:string; image:string; };
type BookingStatus = 'PENDING'|'CONFIRMED'|'MOBILIZING'|'ON SITE'|'IN PROGRESS'|'COMPLETED';
type Booking = { id:string; machineryId:string; machineryTitle:string; ownerName:string; customerName:string; location:string; date:string; durationHours:number; baseCost:number; platformFee:number; totalCost:number; ownerEarnings:number; status:BookingStatus; review?:{rating:number; text:string}; };
type Bid = { id:string; operator:string; equipment:string; amount:number; eta:string; rating:number; distance:number; };
type Auction = { id:string; title:string; category:string; location:string; description:string; requiredDate:string; maxPrice:number; lowestBid:number; bidCount:number; status:string; bids:Bid[]; };
type FleetItem = { id:string; equipment:string; registration:string; capacity:string; rate:number; status:string; fuel:number; engineHours:number; telematicsId:string; currentJob:string; };
type Activity = { id:string; label:string; detail:string; time:string; type:string; };

